import re
text = open('/tmp/ajc_blobs/MainProjects_Algebraic-Jacobian-Challenge_AlgebraicJacobian_Picard_PicEtCrossBase.lean', encoding='utf-8').read()

def strip_comments(text):
    out = []
    i = 0
    depth = 0
    n = len(text)
    while i < n:
        if text[i:i+2] == '/-':
            depth += 1
            i += 2
            while i < n and depth > 0:
                if text[i:i+2] == '/-':
                    depth += 1; i += 2
                elif text[i:i+2] == '-/':
                    depth -= 1; i += 2
                else:
                    if text[i] == '\n': out.append('\n')
                    i += 1
            continue
        if text[i:i+2] == '--':
            j = text.find('\n', i)
            if j == -1: i = n
            else:
                out.append('\n'); i = j+1
            continue
        out.append(text[i]); i += 1
    return ''.join(out)

stripped = strip_comments(text)
matches = [(i,l) for i,l in enumerate(stripped.split('\n'),1) if re.search(r'\bsorry\b', l)]
print("body sorry occurrences after stripping comments:", len(matches))
for m in matches: print(m)
